func _signal_fired(name: String) -> bool:
        for entry in signals_log:
                if entry[0] == name:
                        return true
        return false

func _signal_count(name: String) -> int:
        var c: int = 0
        for entry in signals_log:
                if entry[0] == name:
                        c += 1
        return c
